{
  "per_column": [
    {
      "name": "incident_category",
      "analytical_usefulness": 0.95,
      "source_groundedness": 0.95,
      "rationale": "Directly the grouping axis the query calls for; a richer categorization than the raw 'category' column. Values map soundly from short_description (WiFi->network_connectivity, VPN->vpn_connectivity, database->database_access)."
    },
    {
      "name": "affected_system_component",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.85,
      "rationale": "Provides a genuine additional axis for comparing resolution duration. Mostly well-grounded, though component (e.g. 'vpn_server', 'database_server') is a mild inference from symptom text rather than explicit; reasonable warranted inference."
    },
    {
      "name": "incident_symptom_type",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.9,
      "rationale": "Symptom (cannot_connect, access_denied) is a sound reading of short_description and gives a useful axis affecting duration. Unknown for silent 'Printing issues' row is correct behaviour."
    },
    {
      "name": "scope_indicator",
      "analytical_usefulness": 0.75,
      "source_groundedness": 0.55,
      "rationale": "Scope (individual vs system_wide vs location_specific) is analytically relevant to duration, but many source texts do not clearly state scope; 'individual_user' vs 'location_specific' assignments appear partly invented where the text is silent (e.g. generic VPN descriptions)."
    },
    {
      "name": "resolver_match",
      "analytical_usefulness": 0.3,
      "source_groundedness": 0.5,
      "rationale": "Meaning is opaque and not clearly tied to the duration-by-category/priority query. Basis for true/false is unclear from the provided fields; appears to compare resolver identity but derivation is not evident from source text."
    },
    {
      "name": "opened_hour_of_day",
      "analytical_usefulness": 0.6,
      "source_groundedness": 0.9,
      "rationale": "Cleanly derivable from opened_at timestamp and can plausibly influence resolution duration, giving a secondary axis, though not part of the core category/priority query. Well grounded."
    },
    {
      "name": "repeat_incident_signal",
      "analytical_usefulness": 0.5,
      "source_groundedness": 0.45,
      "rationale": "Repeat detection could inform duration analysis, but its derivation from available fields is unclear and the true/false labels are not evidently supported by the sampled source text; risk of unsupported assertion."
    }
  ],
  "analytical_usefulness": 0.72,
  "source_groundedness": 0.72,
  "rationale": "The core columns (incident_category, symptom, affected_component) give strong, well-grounded axes directly serving the duration-by-category/priority query. Secondary columns (opened_hour, scope) add plausible modeling axes. Weaker columns (resolver_match, repeat_incident_signal) have opaque analytical value and questionable groundedness since their derivation is not supported by the visible source fields."
}

